from pathlib import Path
R=Path('reports/player-impact-v34');P=Path('reports/player-impact-v33');O=Path('reports/player-impact-v31')
def put(name,text):
 f=R/name;assert not f.exists(),f;f.write_text(text,encoding='utf-8')
s=(P/'prepare-data.mjs').read_text(encoding='utf-8').replace('reports/player-impact-v33','reports/player-impact-v34')
s=s.replace("from '../player-impact-v30/input.mjs'","from './input.mjs'").replace("import {supplyFlow} from '../player-impact-v11/model.mjs';","import {anchoredFlow} from './model.mjs';")
s=s.replace("import {sourceSupportedSelf} from '../../src/source_self_opportunities.js';\n",'').replace('flow=supplyFlow(ls)','flow=anchoredFlow(ls)')
s=s.replace('const supported=sourceSupportedSelf(flow,ls.map(p=>p.opportunityMeasurement)),unused=flow.self.map((x,i)=>Math.max(0,x-supported[i]));','const supported=flow.self,unused=flow.self.map(()=>0);')
start=s.index("design:'");end=s.index("',\n coverage",start)
s=s[:start]+"design:'Fixed source-self floor flow v34; attemptBase/selfMakeBase/assistedMakeExpected hold predictions and all slope columns are zero. Same source counts and actual mean-stint energy as v33. Source role/probability descriptors contain full-season outcomes, not blind/causal. No parameter fit, rank/name/wins tuning or runtime adoption."+s[end:]
put('prepare-data.mjs',s)
s=(P/'verify-data.py').read_text(encoding='utf-8').replace('reports/player-impact-v33','reports/player-impact-v34');put('verify-data.py',s)
s=(P/'verify-probability.mjs').read_text(encoding='utf-8').replace('reports/player-impact-v33','reports/player-impact-v34')
s=s.replace("from '../player-impact-v30/ovr-input.mjs'","from './ovr-input.mjs'").replace("'reports/player-impact-v30/engine.mjs'","'reports/player-impact-v34/engine.mjs'")
s=s.replace('actual v30 game closure','actual v34 game closure');put('verify-probability.mjs',s)
s=(O/'verify-profiles.mjs').read_text(encoding='utf-8').replace('reports/player-impact-v31','reports/player-impact-v34');put('verify-profiles.mjs',s)
s=(O/'verify-equivalence.mjs').read_text(encoding='utf-8').replace('reports/player-impact-v31','reports/player-impact-v34')
s=s.replace('receiveOpportunityRate:0,selfOpportunityRate:m.terminalOpportunityRate','receiveOpportunityRate:0,selfOpportunityRate:m.terminalOpportunityRate,passOpportunityRate:0,passStolenPerMinute:0')
s=s.replace("['src/source_self_opportunities.js',root+'/model.mjs'","[root+'/model.mjs'")
s=s.replace('Controlled source-role inputs with zero received-demand priors ensure old residual self never exceeds source self.','Controlled no-pass/no-receive source inputs make old and new transport identical, with all terminal room used as self.');put('verify-equivalence.mjs',s)
s=(O/'export-players.py').read_text(encoding='utf-8').replace('reports/player-impact-v31','reports/player-impact-v34')
s=s.replace('sourceStrictMeanSupportedSelf_v31','sourceStrictMeanAssignedSelf_v34').replace("'supportedSelf'","'assignedSelf'")
s=s.replace('sourceStrictMeanRemovedSelf','sourceStrictMeanAddedSelf').replace("'unfilledReceive'","'addedSelf'")
s=s.replace('mean70SupportedSelf_v31','mean70AssignedSelf_v34').replace("mf['supportedSelf']","mf['assignedSelf']")
put('export-players.py',s)
print('Created source, probability, equivalence and all-player checks.')
